body_md:
\label{t.main}
For every $t\geqslant0$, $h\in\mathbb R^{\mathscr S}$, and $T$ satisfying $T_s\geqslant t\partial_s\xi(\lambda)$ for every $s\in\mathscr S$, we have
\begin{equation}\label{e.main.martingale}
 \lim_{N\to\infty}\overline F_N(t,0)
 =\inf_{\alpha\in\mathcal M_T}
 \left\{\mathcal C_T(\alpha)-\sum_s\lambda_sh_s\alpha_s(0)
                         +\mathcal K^{T}_{t,\alpha}(0)\right\},
\end{equation}
and the infimum is attained.

\label{t.slices}
For every $t\geqslant0$ and $q\in\mathcal Q_2^{\mathscr S}$, there is a continuous function $m\mapsto f_m(t,q)$ on $[-1,1]^{\mathscr S}$ such that
\begin{equation}\label{e.slice.convergence}
\lim_{N \to \infty} \sup_k\bigl|\overline F_{N,k}(t,q)-f_{m_{N,k}}(t,q)\bigr|
        = 0.
\end{equation}
For every $m\in[-1,1]^{\mathscr S}$, the function $f_m$ is the Lipschitz viscosity solution of
\begin{equation}\label{e.slice.hj}
 \partial_t f_m-\int_0^1\xi(\partial_q f_m(r))\,\mathrm d r=0,
 \qquad f_m(0,\cdot)=\psi_m,
\end{equation}
on the closed cone $\mathcal Q_2^{\mathscr S}$, in the sense specified in Section~\ref{s.hj}. It has the Hopf representation
\begin{equation}\label{e.slice.hopf}
 f_m(t,q)=\sup_{p\in\mathcal Q_\infty^{\mathscr S}}\inf_{q'\in\mathcal Q_\infty^{\mathscr S}}
 \left\{\psi_m(q')+\int_0^1\bigl(q(r)-q'(r)\bigr)\cdot p(r)\,\mathrm d r
       +t\int_0^1\xi(p(r))\,\mathrm d r\right\}.
\end{equation}
For every $q \in \mathcal Q_\infty^\mathscr S$ and every $T \in (0,\infty)^\mathscr S$ with $T_s\geqslant\|q_s\|_\infty+t\partial_s\xi(\lambda)$ for every $s$, we have
\begin{equation}\label{e.slice.martingale}
 f_m(t,q)=\inf_{\alpha\in\mathcal M_T^m}
 \left\{\mathcal C_T(\alpha)+\int_0^1\mathcal K^{T}_{t,\alpha}(q(r))\,\mathrm d r\right\},
\end{equation}
and the infimum is attained.

\label{l.comparison}
Let $q$ be regular. Let $W_1$ and $W_2$ be continuous functions on $[0,1]\times\mathbb R^N$ with bounded spatial gradients, which on each piece of $q$ are classical solutions of $\mathcal L[W_i]=\phi_i$, where $\phi_i$ is bounded on $[0,1)\times\mathbb R^N$ and continuous on each piece. For every $r\in[0,1]$, we have
\begin{equation}\label{e.comparison}
 \sup_{x\in\mathbb R^N}|W_1(r,x)-W_2(r,x)|
 \leqslant\sup_{x\in\mathbb R^N}|W_1(1,x)-W_2(1,x)|
  +\int_r^1\sup_{x\in\mathbb R^N}|\phi_1(u,x)-\phi_2(u,x)|\,\mathrm d u .
\end{equation}
If moreover $\phi_1\leqslant\phi_2$ on $[0,1)\times\mathbb R^N$ and $W_1(1,\cdot)\geqslant W_2(1,\cdot)$, then $W_1\geqslant W_2$ on $[0,1]\times\mathbb R^N$.

\label{d.free.energy}
For $t\geqslant0$ and a regular path $q$, let
\begin{equation*}
 H^{\mathrm{br}}_N(\sigma):=\sqrt{2t}H_N(\sigma)+X_1\cdot\sigma
       -Nt\xi(\lambda_N)-N\lambda_N\cdot q(1)-A_q,
\end{equation*}
and define
\begin{equation}\label{e.def.branch.free.energy}
 \overline F_{N,\Omega}(t,q):=-\frac1N\mathbb E\log
          \sum_{\sigma\in\Omega}w(\sigma)e^{H^{\mathrm{br}}_N(\sigma)},
\end{equation}
the dependence on the choice of the weight $w$ being kept implicit. 
We write $\overline F_{N,k}:=\overline F_{N,\Omega_{N,k}}$ for a slice with the weights $2^{-N}$, and $\overline F_N:=\overline F_{N,\Sigma_N}$ for the full cube with the weights $2^{-N}e^{h^{(N)}\cdot\sigma}$.

\label{l.ito}
For every $g$, $X_0$, and almost every~$B$, we have
\begin{equation}\label{e.ito.identity}
 U(1,X_1;g)-A_q=U(0,X_0;g)+\int_0^1\boldsymbol m_r\cdot\sqrt{2D(r)}\,\mathrm d B_r.
\end{equation}
Consequently
\begin{equation}\label{e.free.energy.V}
 \overline F_{N,\Omega}(t,q)=t\xi(\lambda_N)+\lambda_N\cdot q(1)-\frac1N\mathbb E\,U(0,X_0;g).
\end{equation}

\label{r.control}
The same calculation, applied to the controlled process $Y^v_r:=X_0+\int_0^r2uD(u)v_u\,\mathrm d u+\int_0^r\sqrt{2D(u)}\,\mathrm d B_u$ for a progressively measurable $v$ with values in $[-1,1]^N$, gives
\begin{multline*}
 U(0,X_0;g)-\mathbb E_B\left[U(1,Y_1^v;g)-\int_0^1r\,v_r\cdot D(r)v_r\,\mathrm d r\right]\\
 =\mathbb E_B\int_0^1r\,\bigl|v_r-\nabla U(r,Y_r^v;g)\bigr|_{D(r)}^2\,\mathrm d r\geqslant0,
\end{multline*}
where $|w|_D^2:=w\cdot Dw$, with equality exactly for the branch. Thus $U(0,X_0;g)$ is the value of a stochastic control problem, the branch is its optimal state, and $\overline F_{N,\Omega}(t,q)$ could equivalently be defined by maximizing the expected terminal log partition function minus the quadratic running cost, separately for each realization of $(g,X_0)$. This is the finite-$N$ counterpart of the control representation of the Parisi functional \cite{auffinger2015parisi, jagtob}.

\label{l.symmetries}
Let $q$ be regular, and fix a realization of $g$.
\begin{enumerate}
\item For every $y\in\mathbb R^N$ and $c\in\mathbb R$, the solution of \eqref{e.branch.pde} with the terminal datum $x\mapsto U(1,x+y;g)+c$ is $(r,x)\mapsto U(r,x+y;g)+c$.
\item Let $\{1,\ldots,N\}=B_1\cup\cdots\cup B_p$ be a partition into blocks, each contained in a single species, and suppose that the terminal datum is of the form $U(1,x;g)=\sum_\ell U_\ell(1,x_{B_\ell})$, where $x_{B_\ell}$ denotes the restriction of $x$ to the coordinates in $B_\ell$ and each $U_\ell(1,\cdot)$ has bounded derivatives of all orders. Then $U(r,x;g)=\sum_\ell U_\ell(r,x_{B_\ell})$, where $U_\ell$ solves \eqref{e.branch.pde} in dimension $|B_\ell|$, with $D$ replaced by its restriction to the coordinates in $B_\ell$, and with the terminal datum $U_\ell(1,\cdot)$.
\item Suppose that $S\Omega=\Omega$ and $w\circ S=w$. Then, for every such permutation $S$,
\begin{equation}\label{e.permutation.symmetry}
\begin{gathered}
 U(r,Sx;O_Sg)=U(r,x;g),\qquad
 \nabla U(r,Sx;O_Sg)=S\nabla U(r,x;g),\\
 \nabla^2U(r,Sx;O_Sg)=S\nabla^2U(r,x;g)S^{\mathsf T}.
\end{gathered}
\end{equation}
\end{enumerate}

\label{l.response}
Let $b:\Omega\to\mathbb R$. For every $r\in[0,1]$, we have 
\begin{align}
 \partial_yU^y(r,X_r;g)\big|_{y=0}&=\langle b\rangle_r,
      \label{e.response.first}\\
 \Xi_r(b)&=r\operatorname{Var}_r(b)
       +\int_r^1\mathbb E\bigl[\operatorname{Var}_u(b)\bigm|\mathcal G_r\bigr]\,\mathrm d u.
      \label{e.response.second}
\end{align}
In particular, $\langle\sigma\rangle_r=\nabla U(r,X_r;g)=\boldsymbol m_r$, and the response matrix satisfies
\begin{equation}\label{e.response.matrix}
 K_r=rC_r+\int_r^1\mathbb E[C_u\mid\mathcal G_r]\,\mathrm d u,
 \qquad
 rC_r\preceq K_r\preceq C_r\preceq N\mathrm{Id}.
\end{equation}
Moreover,
\begin{equation}\label{e.mean.martingale}
 \mathrm d\boldsymbol m_r=K_r\sqrt{2D(r)}\,\mathrm d B_r .
\end{equation}

Let $\mathcal A:=\partial_r+\operatorname{tr}(D\nabla^2)+2r(D\nabla U)\cdot\nabla$ be the backward generator of the branch \eqref{e.branch.sde}. Differentiating \eqref{e.branch.pde} once and twice in $y$ at $y=0$, we find that $W:=\partial_yU^y|_{y=0}$ and $W_2:=\partial_y^2U^y|_{y=0}$ solve
\begin{equation*}
 \mathcal AW=0,\qquad
 \mathcal AW_2+2r\,\nabla W\cdot D\nabla W=0,
\end{equation*}
with terminal conditions $W(1,x)=\partial_yU^y(1,x;g)|_{y=0}$ and $W_2(1,x)=\partial_y^2U^y(1,x;g)|_{y=0}$. These are the mean and the variance of $b$ under the Gibbs measure with field $x$, so that $W(1,X_1)=\langle b\rangle_1$ and $W_2(1,X_1)=\operatorname{Var}_1(b)$ by \eqref{e.sampled.configuration}.

By It\^o's formula, $M_r:=W(r,X_r)$ is a bounded continuous martingale with terminal value $\langle b\rangle_1=\mathbb E[b(\sigma)\mid\mathcal G_1]$. Hence $M_r=\mathbb E[b(\sigma)\mid\mathcal G_r]=\langle b\rangle_r$, which is \eqref{e.response.first}, and $\mathrm d[M]_r=2\nabla W\cdot D\nabla W(r,X_r)\,\mathrm d r$. Set $V_r:=\operatorname{Var}_r(b)$. We claim that
\begin{equation}\label{e.response.martingale}
 \Xi_r(b)-rV_r+\int_0^rV_u\,\mathrm d u\qquad\text{is a martingale.}
\end{equation}
Since $\Xi_1(b)=W_2(1,X_1)=V_1$, the terminal value of this martingale is $\int_0^1V_u\,\mathrm d u$, and \eqref{e.response.second} follows by conditioning on $\mathcal G_r$. To prove the claim, we note that three processes are martingales: first, $\Xi_r(b)+\int_0^ru\,\mathrm d[M]_u$, by It\^o's formula applied to $W_2(r,X_r)$ and the equation for $W_2$; second, $V_r+[M]_r=\mathbb E[b(\sigma)^2\mid\mathcal G_r]-(M_r^2-[M]_r)$, by the tower property and the martingale property of $M^2-[M]$; third, $rY_r-\int_0^rY_u\,\mathrm d u$ for every bounded martingale $Y$, as a direct computation of conditional expectations shows. Applying the third fact to $Y:=V+[M]$ and subtracting the result from the first martingale, we find that
\begin{equation*}
 \Xi_r(b)-rV_r+\int_0^rV_u\,\mathrm d u
 +\Bigl(\int_0^ru\,\mathrm d[M]_u-r[M]_r+\int_0^r[M]_u\,\mathrm d u\Bigr)
\end{equation*}
is a martingale, and the expression in parentheses vanishes identically, by integration by parts for the continuous increasing process $[M]$. This proves \eqref{e.response.martingale}.

For $b(\sigma)=c\cdot\sigma$ with $c\in\mathbb R^N$, we have $U^y(1,x;g)=U(1,x+yc;g)$, so $U^y(r,x;g)=U(r,x+yc;g)$ by Lemma~\ref{l.symmetries}(1), and thus $W=c\cdot\nabla U$ and $W_2=c\cdot\nabla^2Uc$. Now \eqref{e.response.first} gives $c\cdot\nabla U(r,X_r;g)=\langle c\cdot\sigma\rangle_r$, and \eqref{e.response.second} gives $c\cdot K_rc=r\,c\cdot C_rc+\int_r^1\mathbb E[c\cdot C_uc\mid\mathcal G_r]\,\mathrm d u$; polarization yields \eqref{e.response.matrix}. The lower bound on $K_r$ follows from $C_u\succeq0$. For the upper bound, the conditional variance decomposition of the vector $\sigma$ reads
\begin{equation*}
 C_r=\mathbb E[C_u\mid\mathcal G_r]+\mathbb E\bigl[(\boldsymbol m_u-\boldsymbol m_r)(\boldsymbol m_u-\boldsymbol m_r)^{\mathsf T}\bigm|\mathcal G_r\bigr]
 \succeq\mathbb E[C_u\mid\mathcal G_r]
 \qquad(r\leqslant u),
\end{equation*}
and $c\cdot C_rc\leqslant\langle(c\cdot\sigma)^2\rangle_r\leqslant N|c|^2$. Finally, differentiating \eqref{e.branch.pde} in $x$ shows that each component of $\nabla U$ solves $\mathcal A(\partial_{x_i}U)=0$, and It\^o's formula gives \eqref{e.mean.martingale}.

\label{l.energy}
The function $\Gamma$ is absolutely continuous on $[0,1]$ and
\begin{equation}\label{e.energy.identity}
 \Gamma'(r)=\frac2N\mathbb E\operatorname{tr}\bigl(K_rD(r)K_r\bigr),
 \qquad 0\leqslant\Gamma(0)\leqslant\Gamma(1)\leqslant1 .
\end{equation}
Each component $p_{N,s}$ is increasing with values in $[0,\lambda_{N,s}]$, and $\sum_sp_{N,s}\leqslant1$. If $\dot q_s\geqslant\kappa>0$ on $[0,1)$ for every species $s$, then
\begin{equation}\label{e.energy.bound}
 \int_0^1\mathbb E\operatorname{tr} K_r^2\,\mathrm d r\leqslant\frac{N}{2\kappa}.
\end{equation}

By \eqref{e.mean.martingale}, It\^o's formula gives
\begin{equation*}
 \mathrm d|P_s\boldsymbol m_r|^2=2P_s\boldsymbol m_r\cdot\mathrm d\boldsymbol m_r
 +2\operatorname{tr}\bigl(P_sK_rD(r)K_rP_s\bigr)\mathrm d r,
\end{equation*}
whose drift is nonnegative. Taking expectations and summing over $s$ gives \eqref{e.energy.identity} and the monotonicity of $p_{N,s}$; the bounds follow from $|P_s\boldsymbol m_r|^2\leqslant|I_{N,s}|$. Under the lower bound $D(r)\succeq\kappa\mathrm{Id}$ on the slopes, we have $\operatorname{tr}(K_rDK_r)\geqslant\kappa\operatorname{tr} K_r^2$, and integrating \eqref{e.energy.identity} gives \eqref{e.energy.bound}.

\label{t.derivatives}
Let $t\geqslant0$ and let $q$ be a regular path. For every admissible variation $h$, we have
\begin{equation}\label{e.derivatives}
 \begin{aligned}
 \frac{\mathrm d}{\mathrm d\varepsilon}\overline F_{N,\Omega}(t,q+\varepsilon h)\Big|_{\varepsilon=0}
   &=\int_0^1h(r)\cdot\mathbb E\langle R_N\rangle_r\,\mathrm d r,\\[2pt]
 \partial_t\overline F_{N,\Omega}(t,q)
   &=\int_0^1\mathbb E\langle\xi(R_N)\rangle_r\,\mathrm d r .
 \end{aligned}
\end{equation}

Let $q^\varepsilon:=q+\varepsilon h$, let $U^\varepsilon$ be the corresponding solution of \eqref{e.branch.pde}, and let $X^\varepsilon_0\sim\mathcal N(0,2\operatorname{diag}(q(0))+2\varepsilon\operatorname{diag}(h(0)))$. Let $D_h(r):=\operatorname{diag}(\dot h(r))$. By \eqref{e.free.energy.V},
\begin{equation}\label{e.path.derivative.split}
 \frac{\mathrm d}{\mathrm d\varepsilon}\overline F_{N,\Omega}(t,q^\varepsilon)\Big|_{\varepsilon=0}
 =\lambda_N\cdot h(1)
 -\frac1N\frac{\mathrm d}{\mathrm d\varepsilon}\mathbb E\,U^\varepsilon(0,X_0;g)\Big|_{\varepsilon=0}
 -\frac1N\frac{\mathrm d}{\mathrm d\varepsilon}\mathbb E\,U(0,X^\varepsilon_0;g)\Big|_{\varepsilon=0}.
\end{equation}
The last term is the derivative of a Gaussian expectation with respect to its covariance, and equals
\begin{equation}\label{e.root.term}
 -\frac1N\mathbb E\operatorname{tr}\bigl(\nabla^2U(0,X_0;g)\operatorname{diag}(h(0))\bigr)
 =-\frac1N\sum_sh_s(0)\,\mathbb E\operatorname{tr} K_{0,ss}.
\end{equation}
For the middle term, $W:=\partial_\varepsilon U^\varepsilon|_{\varepsilon=0}$ solves the linearized equation
\begin{equation*}
 \mathcal AW=-\operatorname{tr}(D_h\nabla^2U)-r\,\nabla U\cdot D_h\nabla U,
 \qquad W(1,\cdot)=0,
\end{equation*}
where $\mathcal A$ is the backward generator of the branch, as in the proof of Lemma~\ref{l.response}. It\^o's formula along the branch gives
\begin{equation*}
 \mathbb E\,W(0,X_0)=\int_0^1\mathbb E\bigl[\operatorname{tr}(D_h(r)K_r)+r\,\boldsymbol m_r\cdot D_h(r)\boldsymbol m_r\bigr]\,\mathrm d r.
\end{equation*}
We now express the integrand through the Gibbs measures, for a general diagonal matrix. Let $c\in\mathbb R^{\mathscr S}$. Since $C_r+\boldsymbol m_r\boldsymbol m_r^{\mathsf T}=\langle\sigma\sigma^{\mathsf T}\rangle_r$ has unit diagonal, the response identity \eqref{e.response.matrix} gives
\begin{equation*}
\begin{split}
 \operatorname{tr}(\operatorname{diag}(c)K_r)+r\,\boldsymbol m_r\cdot\operatorname{diag}(c)\boldsymbol m_r
 &=r\operatorname{tr}\bigl(\operatorname{diag}(c)\langle\sigma\sigma^{\mathsf T}\rangle_r\bigr)
     +\int_r^1\operatorname{tr}\bigl(\operatorname{diag}(c)\mathbb E[C_u\mid\mathcal G_r]\bigr)\,\mathrm d u\\
 &=Nc\cdot\left(r\lambda_N
     +\int_r^1\mathbb E\bigl[\lambda_N-S_u\bigm|\mathcal G_r\bigr]\,\mathrm d u\right),
\end{split}
\end{equation*}
where we used \eqref{e.trace.covariance} in the last step. Taking expectations and recalling that $\mathbb E S_u=p_N(u)$, we obtain, for every $c\in\mathbb R^{\mathscr S}$ and $r\in[0,1]$,
\begin{equation}\label{e.a.identity}
 \frac1N\mathbb E\bigl[\operatorname{tr}(\operatorname{diag}(c)K_r)+r\,\boldsymbol m_r\cdot\operatorname{diag}(c)\boldsymbol m_r\bigr]
 =c\cdot\mathfrak a(r),
 \qquad
 \mathfrak a(r):=\lambda_N-\int_r^1p_N(u)\,\mathrm d u .
\end{equation}
We apply this identity twice. With $c=\dot h(r)$, so that $\operatorname{diag}(c)=D_h(r)$, it gives the middle term in \eqref{e.path.derivative.split}:
\begin{equation*}
 -\frac1N\frac{\mathrm d}{\mathrm d\varepsilon}\mathbb E\,U^\varepsilon(0,X_0;g)\Big|_{\varepsilon=0}
 =-\frac1N\mathbb E\,W(0,X_0)
 =-\int_0^1\dot h(r)\cdot\mathfrak a(r)\,\mathrm d r .
\end{equation*}
With $c=h(0)$ and $r=0$, the quadratic term in $\boldsymbol m_r$ vanishes, and it gives the root term \eqref{e.root.term}:
\begin{equation*}
 -\frac1N\mathbb E\operatorname{tr}\bigl(\nabla^2U(0,X_0;g)\operatorname{diag}(h(0))\bigr)
 =-\frac1N\mathbb E\operatorname{tr}\bigl(\operatorname{diag}(h(0))K_0\bigr)
 =-h(0)\cdot\mathfrak a(0).
\end{equation*}
The last two terms in \eqref{e.path.derivative.split} together form the derivative of $\mathbb E\,U^\varepsilon(0,X^\varepsilon_0;g)$, in which $\varepsilon$ enters both through the equation and through the initial law; we have shown that
\begin{equation}\label{e.V.path.derivative.raw}
 \frac1N\frac{\mathrm d}{\mathrm d\varepsilon}\mathbb E\,U^\varepsilon(0,X^\varepsilon_0;g)\Big|_{\varepsilon=0}
 =h(0)\cdot\mathfrak a(0)+\int_0^1\dot h(r)\cdot\mathfrak a(r)\,\mathrm d r .
\end{equation}
Since $h$ and $\mathfrak a$ are Lipschitz, an integration by parts gives
\begin{align*}
h(0)\cdot\mathfrak a(0)+  \int_0^1\dot h(r)\cdot\mathfrak a(r)\,\mathrm d r
 & =h(1)\cdot\mathfrak a(1)-\int_0^1h(r)\cdot\mathfrak a'(r)\,\mathrm d r,


\end{align*}
and using also that $\mathfrak a'=p_N$ and $\mathfrak a(1)=\lambda_N$, we thus obtain
\begin{equation}\label{e.V.path.derivative}
 \frac1N\frac{\mathrm d}{\mathrm d\varepsilon}\mathbb E\,U^\varepsilon(0,X^\varepsilon_0;g)\Big|_{\varepsilon=0}
 =\lambda_N\cdot h(1)-\int_0^1h(r)\cdot p_N(r)\,\mathrm d r .
\end{equation}
Inserting this into \eqref{e.path.derivative.split}, the self-overlap terms $\lambda_N\cdot h(1)$ cancel, and
\begin{equation*}
 \frac{\mathrm d}{\mathrm d\varepsilon}\overline F_{N,\Omega}(t,q^\varepsilon)\Big|_{\varepsilon=0}
 =\int_0^1h(r)\cdot p_N(r)\,\mathrm d r
 =\int_0^1h(r)\cdot\mathbb E\langle R_N\rangle_r\,\mathrm d r ,
\end{equation*}
by the definition \eqref{e.def.S.p} of $p_N$. This is the first identity in \eqref{e.derivatives}.

\label{p.extension}
For all regular paths $q,q'$ and all $t,t'\geqslant0$, we have
\begin{equation}\label{e.finite.lipschitz}
 |\overline F_{N,\Omega}(t,q)-\overline F_{N,\Omega}(t',q')|
 \leqslant\sum_{s\in\mathscr S}\lambda_{N,s}\|q_s-q'_s\|_{L^1}+\xi(\mathbf1)\,|t-t'|
 \leqslant\|q-q'\|_{L^1}+\xi(\mathbf1)\,|t-t'|.
\end{equation}
Consequently, $\overline F_{N,\Omega}$ extends uniquely to a function on $[0,\infty)\times\mathcal Q_1^{\mathscr S}$ satisfying \eqref{e.finite.lipschitz}, and we denote this extension by the same symbol. For a slice, this extension is the enriched slice free energy $\overline F_{N,k}(t,q)$ appearing in Theorem~\ref{t.slices}.

\label{l.zero}
For every $t\geqslant0$,
\begin{equation}\label{e.zero}
 \overline F_{N,\Omega}(t,0)=-\frac1N\mathbb E\log\sum_{\sigma\in\Omega}w(\sigma)
 \exp\bigl(\sqrt{2t}H_N(\sigma)-Nt\xi(\lambda_N)\bigr),
\end{equation}
which is the free energy \eqref{e.def.slice.zero} for a slice, and the free energy \eqref{e.def.free.energy} for the full cube with the weights $2^{-N}e^{h^{(N)}\cdot\sigma}$.

For $\varepsilon>0$, the path $q^\varepsilon(r):=\varepsilon(1+r)\mathbf1$ is regular, with $D^\varepsilon=\varepsilon\mathrm{Id}$ and initial field $X^\varepsilon_0=\sqrt{2\varepsilon}\,Z$, and $\overline F_{N,\Omega}(t,q^\varepsilon)\to\overline F_{N,\Omega}(t,0)$ as $\varepsilon\to0$ by \eqref{e.finite.lipschitz}. Let $U^\varepsilon$ be the solution of \eqref{e.branch.pde} for $q^\varepsilon$, with operator $\mathcal L^\varepsilon$, and let $W(r,x):=U(1,x;g)$ be the terminal function \eqref{e.def.terminal}, held constant in $r$. Since $\nabla^2W$ is a covariance matrix of $\sigma$, of trace at most $N$, and $|\nabla W|^2\leqslant N$, we have $\mathcal L^\varepsilon[W]=\varepsilon(\operatorname{tr}\nabla^2W+r|\nabla W|^2)\in[0,2\varepsilon N]$, while $\mathcal L^\varepsilon[U^\varepsilon]=0$ and both functions have the same terminal datum, so Lemma~\ref{l.comparison} gives $|U^\varepsilon(0,\cdot)-U(1,\cdot\,;g)|\leqslant2\varepsilon N$. By \eqref{e.heat.interpolation}, $0\leqslant\mathbb E\,U(1,\sqrt{2\varepsilon}\,Z;g)-\mathbb E\,U(1,0;g)\leqslant N\varepsilon$. Hence $|\mathbb E\,U^\varepsilon(0,X^\varepsilon_0;g)-\mathbb E\,U(1,0;g)|\leqslant3\varepsilon N$, and \eqref{e.free.energy.V}, in which $\lambda_N\cdot q^\varepsilon(1)=2\varepsilon$, gives
\begin{equation*}
 \Bigl|\overline F_{N,\Omega}(t,q^\varepsilon)-t\xi(\lambda_N)+\frac1N\mathbb E\,U(1,0;g)\Bigr|\leqslant5\varepsilon .
\end{equation*}
Letting $\varepsilon\to0$ yields $\overline F_{N,\Omega}(t,0)=t\xi(\lambda_N)-\frac1N\mathbb E\,U(1,0;g)$, which is \eqref{e.zero}, since $U(1,0;g)=\log\sum_{\sigma\in\Omega}w(\sigma)e^{\sqrt{2t}H_N(\sigma)}$.

\label{t.remainder}
Let $\kappa>0$, and let $q$ be a regular path with $\dot q_s\geqslant\kappa$ on every piece, for every species $s$. For every slice $\Omega=\Omega_{N,k}$, every $\delta\in\{1,\frac12,\frac13,\ldots\}$ and every $t\geqslant0$, we have
\begin{equation}\label{e.W.bound}
 \mathscr W_N(t,q)\leqslant13\delta+\frac{5}{2\kappa N\delta^2}.
\end{equation}
Consequently, for every $N$, every slice, every $t\geqslant0$ and every such path, we have
\begin{equation}\label{e.small.defect}
 \Bigl|\partial_t\overline F_{N,k}(t,q)
              -\mathcal H\bigl(\partial_q\overline F_{N,k}(t,q)\bigr)\Bigr|
                          \leqslant15M_\xi(\kappa N)^{-1/3}.
\end{equation}

\label{l.joint.density}
The law of $(g,X,\sigma)$ has density
\begin{equation}\label{e.joint.density}
 2^{-N}\exp\left(\sqrt{2t}\,g\cdot v_\sigma+x_1\cdot\sigma
                         -\int_0^1U(r,x_r;g)\,\mathrm d r\right)
\end{equation}
at $(g,x,\sigma)$ with respect to the product of $\gamma$ and the counting measure on $\Omega$.

\label{l.convexity}
For every $r\in[0,1]$, the map $(x,g)\mapsto U(r,x;g)$ is smooth, with derivatives of all orders bounded and continuous in $(r,x,g)$, and it is convex, with
\begin{equation}\label{e.joint.hessian.bound}
 0\preceq\nabla^2_{(x,g)}U(r,x;g)\preceq N\bigl(1+2t\xi(\lambda_N)\bigr)\mathrm{Id} .
\end{equation}

\label{p.posterior}
Let $q$ be regular. For every slice $\Omega_{N,k}$, every deterministic $a\in L^2([0,1])$ and every species $s$, we have
\begin{equation}\label{e.posterior.variance}
 \operatorname{Var}\left(\int_0^1a(r)L_{r,s}\,\mathrm d r\right)
 \leqslant\frac4{N^2}\int_0^1a(r)^2\,
                   \mathbb E\operatorname{tr}\bigl(K_{r,ss}C_{r,ss}\bigr)\,\mathrm d r .
\end{equation}

\label{l.algebra}
Let $(A_r)_{0\leqslant r\leqslant1}$ be a bounded measurable family of positive semidefinite matrices of the same size, let $a\in L^2([0,1])$, let $(v_r)_{0\leqslant r\leqslant1}$ be a bounded measurable family of vectors, and let $Q$ be a positive definite matrix with $Q\succeq\int_0^1A_r\,\mathrm d r$. The vector $z:=\int_0^1a(r)A_rv_r\,\mathrm d r$ satisfies
\begin{equation}\label{e.curvature.algebra}
 z\cdot Q^{-1}z\leqslant\int_0^1a(r)^2\;v_r\cdot A_rv_r\,\mathrm d r .
\end{equation}

\label{l.conditional.variance}
Let $q$ be regular, let $\Omega=\Omega_{N,k}$ be a slice, let $a\in L^2([0,1])$ be deterministic, and let $s$ be a species. For every $\tau\in\Omega$,
\begin{equation}\label{e.conditional.variance}
 \operatorname{Var}\left(\int_0^1a(r)L_{r,s}\,\mathrm d r\Bigm|\sigma=\tau\right)
 \leqslant\frac4{N^2}\,\mathbb E\left[\int_0^1a(r)^2\,
   P_s(\sigma-\boldsymbol m_r)\cdot K_rP_s(\sigma-\boldsymbol m_r)\,\mathrm d r\Bigm|\sigma=\tau\right].
\end{equation}

\emph{Step 1: the conditional law.}
Fix $\tau\in\Omega$, and let $f_\tau(g,x)$ denote the density \eqref{e.joint.density} at $(g,x,\tau)$. Then $c_\tau:=\int f_\tau\,\mathrm d\gamma=\mathbb P(\sigma=\tau)>0$, and $\mu_\tau:=c_\tau^{-1}f_\tau\,\gamma$ is the conditional law of $(g,X)$ given $\sigma=\tau$. For a realization $g$ of the disorder and a continuous path $x$, set
\begin{equation}\label{e.def.conditional.observables}
\begin{gathered}
 \theta_r(g,x):=P_s\bigl(\tau-\nabla U(r,x_r;g)\bigr),
 \qquad
 F(g,x):=\frac1N\int_0^1a(r)\left(|I_{N,s}|-\bigl|\theta_r(g,x)\bigr|^2\right)\mathrm d r,\\
 \mathcal E(g,x):=\int_0^1a(r)^2\,\theta_r(g,x)\cdot\nabla^2U(r,x_r;g)\,\theta_r(g,x)\,\mathrm d r .
\end{gathered}
\end{equation}
On the event $\{\sigma=\tau\}$, by \eqref{e.def.L}, $F(g,X)$ is the level average $\int_0^1a(r)L_{r,s}\,\mathrm d r$, and $\mathcal E(g,X)$ is the integral on the right-hand side of \eqref{e.conditional.variance}. Thus \eqref{e.conditional.variance} reads
\begin{equation}\label{e.conditional.variance.mu}
 \operatorname{Var}_{\mu_\tau}(F)\leqslant\frac4{N^2}\,\mathbb E_{\mu_\tau}[\mathcal E] .
\end{equation}
Since $\nabla U\in[-1,1]^N$, $|\theta_r|\leqslant2\sqrt{|I_{N,s}|}$ and $0\preceq\nabla^2U\preceq N\mathrm{Id}$ by \eqref{e.hessian.bounds}, we have
\begin{equation}\label{e.observable.bounds}
 |F|\leqslant3\lambda_{N,s}\|a\|_{L^1},
 \qquad
 0\leqslant\mathcal E\leqslant4N|I_{N,s}|\,\|a\|_{L^2}^2 .
\end{equation}
Moreover, $\nabla U$ and $\nabla^2U$ are Lipschitz continuous in $x$, uniformly in $r$, by Lemma~\ref{l.wellposed}, so that $F(g,\cdot)$ and $\mathcal E(g,\cdot)$ are continuous for the uniform norm on paths.

\emph{Step 2: finite-dimensional approximations of the conditional law.}
For $n\geqslant1$ and $r_j:=j/n$, let $x^{[n]}$ denote the polygonal interpolation of the path $x$ on the mesh $(r_j)_{0\leqslant j\leqslant n}$, that is, the continuous path which agrees with $x$ at the mesh points and is affine on each $[r_j,r_{j+1}]$. It is a linear function of $(x_{r_0},\ldots,x_{r_n})$, it satisfies $\|x^{[n]}\|_\infty\leqslant\|x\|_\infty$, and $x^{[n]}\to x$ uniformly as $n\to\infty$ for every continuous path $x$. Let
\begin{equation}\label{e.approximate.density}
 f_{n,\tau}(g,x):=2^{-N}\exp\left(\sqrt{2t}\,g\cdot v_\tau+x_1\cdot\tau
                         -\int_0^1U\bigl(r,x^{[n]}_r;g\bigr)\,\mathrm d r\right),
\end{equation}
which is $f_\tau$ with the path $x$ replaced by $x^{[n]}$ inside the integral, the function $U$ being unchanged. We first show that these functions are integrable. By Lemma~\ref{l.convexity}, the first derivatives of $U$ in $(x,g)$ are bounded, and $r\mapsto U(r,0;0)$ is continuous on $[0,1]$, so that $|U(r,x;g)|\leqslant C(1+|x|+|g|)$ for some constant $C$. Since $\|x^{[n]}\|_\infty\leqslant\|x\|_\infty$, we obtain
\begin{equation}\label{e.density.envelope}
 f_{n,\tau}(g,x)\leqslant\exp\bigl(C'(1+|g|+\|x\|_\infty)\bigr)
\end{equation}
for a constant $C'$ independent of $n$, and the same bound holds for $f_\tau$. Under $\gamma$, the vector~$g$ is Gaussian, and each coordinate $i\in I_{N,s}$ of the path is a Gaussian initial value plus a Brownian motion run with the clock $2(q_s(r)-q_s(0))$, so $|g|$ and $\|x\|_\infty$ have Gaussian tails, and the right-hand side of \eqref{e.density.envelope} is $\gamma$-integrable. Hence $c_{n,\tau}:=\int f_{n,\tau}\,\mathrm d\gamma$ is finite and positive, and $\mu_{n,\tau}:=c_{n,\tau}^{-1}f_{n,\tau}\,\gamma$ is a probability measure. Since $|U(r,x;g)-U(r,x';g)|\leqslant\sqrt N|x-x'|$, we also have $f_{n,\tau}\to f_\tau$ pointwise, and dominated convergence gives $c_{n,\tau}\to c_\tau$. Consequently, if $(G_n)$ is a uniformly bounded sequence of measurable functions of $(g,x)$ converging pointwise to $G$, then
\begin{equation}\label{e.moments.convergence}
 \mathbb E_{\mu_{n,\tau}}[G_n]=\frac{\int G_nf_{n,\tau}\,\mathrm d\gamma}{c_{n,\tau}}
 \longrightarrow\frac{\int Gf_\tau\,\mathrm d\gamma}{c_\tau}=\mathbb E_{\mu_\tau}[G],
\end{equation}
again by dominated convergence. We write $F_n(g,x):=F(g,x^{[n]})$ and $\mathcal E_n(g,x):=\mathcal E(g,x^{[n]})$ for the functions in \eqref{e.def.conditional.observables} evaluated along the interpolated path.

\emph{Step 3: Gaussian coordinates and the log-density.}
Let $Y:=(g,x_{r_0},\ldots,x_{r_n})\in\mathbb R^d$, where $d$ is the dimension of the disorder space plus $(n+1)N$. Under $\gamma$, this is a centered Gaussian vector whose covariance matrix $\Sigma$ is positive definite: $g$ is a standard Gaussian vector, and, independently of $g$, the initial value $x_{r_0}$ and the increments $x_{r_j}-x_{r_{j-1}}$ are independent and centered, with covariances $2\operatorname{diag}(q(0))$ and $2\operatorname{diag}(q(r_j)-q(r_{j-1}))$, which are positive definite since $q$ is regular. The interpolated path $x^{[n]}$ is a linear function of $Y$, so the density $f_{n,\tau}$ and the functions $F_n$ and $\mathcal E_n$ depend on $(g,x)$ only through $Y$. The law of $Y$ under $\mu_{n,\tau}$ therefore has, relative to Lebesgue measure, a density proportional to $e^{-\Phi_{n,\tau}}$, where
\begin{equation*}
 \Phi_{n,\tau}(Y):=\frac12Y\cdot\Sigma^{-1}Y-\sqrt{2t}\,g\cdot v_\tau-x_1\cdot\tau
                   +\int_0^1U\bigl(r,x^{[n]}_r;g\bigr)\,\mathrm d r .
\end{equation*}
By Lemma~\ref{l.convexity}, $U(r,\cdot\,;\cdot)$ is smooth and convex, with bounded derivatives, and $Y\mapsto(g,x^{[n]}_r)$ is linear. Hence $A_r:=\nabla_Y^2[U(r,x^{[n]}_r;g)]$ is positive semidefinite, bounded and continuous in $(r,Y)$, the function $\Phi_{n,\tau}$ is smooth, and, differentiating under the integral sign,
\begin{equation}\label{e.conditional.curvature}
 \nabla^2\Phi_{n,\tau}=Q:=\Sigma^{-1}+\int_0^1A_r\,\mathrm d r\succeq\Sigma^{-1} .
\end{equation}
The Hessian in \eqref{e.conditional.curvature} exceeds the inverse covariance $\Sigma^{-1}$ of the Gaussian coordinates by the positive semidefinite term $\int_0^1A_r\,\mathrm d r$, which involves differentiation in the disorder $g$ as well as in the field coordinates. 

\emph{Step 4: the gradient of the level average.}
Let $\mathsf J:\mathbb R^N\to\mathbb R^d$ be the linear map $\mathsf Ju:=(0,u,\ldots,u)$, which leaves $g$ unchanged and shifts every $x_{r_j}$, hence the whole path $x^{[n]}$, by $u$. Thus $U(r,x^{[n]}_r;g)$ evaluated at $Y+\mathsf Ju$ equals $U(r,x^{[n]}_r+u;g)$, and differentiating once and twice in $u$ at $u=0$ gives, with $\boldsymbol m^{[n]}_r:=\nabla U(r,x^{[n]}_r;g)$ and $K^{[n]}_r:=\nabla^2U(r,x^{[n]}_r;g)$,
\begin{equation}\label{e.shift.identities}
 \mathsf J^{\mathsf T}\nabla_Y\bigl[U(r,x^{[n]}_r;g)\bigr]=\boldsymbol m^{[n]}_r,
 \qquad
 \mathsf J^{\mathsf T}A_r\mathsf J=K^{[n]}_r .
\end{equation}
Let $\theta^{[n]}_r:=P_s(\tau-\boldsymbol m^{[n]}_r)=\theta_r(g,x^{[n]})$ be the residual along the interpolated path. By the first identity in \eqref{e.shift.identities}, the Jacobian matrix of $\theta^{[n]}_r$ as a function of $Y$ is $-P_s\mathsf J^{\mathsf T}A_r$. Since $A_r$ is symmetric and $P_s\theta^{[n]}_r=\theta^{[n]}_r$, differentiating $F_n$ with $\tau$ fixed gives, with $v_r:=\mathsf J\theta^{[n]}_r$,
\begin{equation}\label{e.gradient.matching}
 N\nabla_YF_n=2\int_0^1a(r)A_rv_r\,\mathrm d r,
 \qquad
 v_r\cdot A_rv_r=\theta^{[n]}_r\cdot K^{[n]}_r\theta^{[n]}_r,
\end{equation}
the second identity being the second one in \eqref{e.shift.identities}. The positive initial variance $q(0)>0$ was used to make $\Sigma$ invertible, but $\Sigma$ will disappear from the estimate once Lemma~\ref{l.algebra} is applied. Since $A_r$ and $\theta^{[n]}_r$ are bounded, $F_n$ is a smooth function of $Y$ with a bounded gradient.

\emph{Step 5: the Brascamp--Lieb inequality.}
We use the Brascamp--Lieb inequality \cite{brascamp1976extensions}, in the following form: if a probability measure on $\mathbb R^d$ has a density proportional to $e^{-\Phi}$, with $\Phi$ smooth and $\nabla^2\Phi\succeq\lambda\mathrm{Id}$ for some $\lambda>0$, then $\operatorname{Var}(G)\leqslant\mathbb E[\nabla G\cdot(\nabla^2\Phi)^{-1}\nabla G]$ for every smooth $G$ with bounded gradient. Applied to $\Phi_{n,\tau}$ and $F_n$, together with \eqref{e.conditional.curvature}, \eqref{e.gradient.matching} and Lemma~\ref{l.algebra} applied to $z:=\frac N2\nabla_YF_n$, it gives
\begin{equation}\label{e.finite.estimate}
\begin{split}
 \operatorname{Var}_{\mu_{n,\tau}}(F_n)
 &\leqslant\mathbb E_{\mu_{n,\tau}}\bigl[\nabla_YF_n\cdot Q^{-1}\nabla_YF_n\bigr]\\
 &\leqslant\frac4{N^2}\,\mathbb E_{\mu_{n,\tau}}\int_0^1a(r)^2\,
     \theta^{[n]}_r\cdot K^{[n]}_r\theta^{[n]}_r\,\mathrm d r
 =\frac4{N^2}\,\mathbb E_{\mu_{n,\tau}}[\mathcal E_n] .
\end{split}
\end{equation}

\emph{Step 6: passage to the limit.}
As $n\to\infty$, $F_n\to F$ and $\mathcal E_n\to\mathcal E$ pointwise, by the uniform convergence of $x^{[n]}$ to $x$ and the continuity noted in Step~1, and these functions are bounded uniformly in $n$, by \eqref{e.observable.bounds} applied along the interpolated paths. By \eqref{e.moments.convergence}, applied to $F_n$, $F_n^2$ and $\mathcal E_n$, both sides of \eqref{e.finite.estimate} converge to the corresponding sides of \eqref{e.conditional.variance.mu}.

Let $F:=\int_0^1a(r)L_{r,s}\,\mathrm d r$. We first show that $F$ is independent of $\sigma$. Let $S$ be a permutation of $\{1,\ldots,N\}$ that preserves each $I_{N,s}$, and let $O_S$ be as in Lemma~\ref{l.symmetries}. Consider the transformation
\begin{equation}\label{e.symmetry}
 (g,x,\sigma)\longmapsto(O_Sg,Sx,S\sigma)
\end{equation}
of the disorder, the path and the configuration. It preserves $\gamma$, because $O_S$ is orthogonal and $S$ commutes with $\operatorname{diag}(q(0))$ and with $D(r)$; it preserves the counting measure on the slice; and it preserves the density \eqref{e.joint.density}, because $O_Sg\cdot v_{S\sigma}=g\cdot v_\sigma$, $Sx_1\cdot S\sigma=x_1\cdot\sigma$, and $U(r,Sx;O_Sg)=U(r,x;g)$ by Lemma~\ref{l.symmetries}(3), the weights $2^{-N}$ being invariant. Hence the law of $(g,X,\sigma)$ is invariant under \eqref{e.symmetry}. Since $\nabla U(r,Sx;O_Sg)=S\nabla U(r,x;g)$ and $P_s$ commutes with $S$, each $L_{r,s}$, and therefore $F$, is invariant under \eqref{e.symmetry}. It follows that $\mathbb E[\varphi(F)\1_{\{\sigma=\tau\}}]=\mathbb E[\varphi(F)\1_{\{\sigma=S\tau\}}]$ for every bounded measurable function $\varphi$, and that $\mathbb P(\sigma=\tau)=\mathbb P(\sigma=S\tau)$, for every $\tau\in\Omega_{N,k}$. These permutations act transitively on $\Omega_{N,k}$, so the conditional law of $F$ given $\sigma=\tau$ does not depend on $\tau$, that is, $F$ is independent of $\sigma$. In particular,
\begin{equation}\label{e.gauge}
 \operatorname{Var}(F)=\operatorname{Var}(F\mid\sigma=\tau)\qquad(\tau\in\Omega_{N,k}).
\end{equation}
Averaging \eqref{e.conditional.variance} over the law of $\sigma$ and using \eqref{e.gauge}, we obtain
\begin{equation*}
 \operatorname{Var}(F)\leqslant\frac4{N^2}\int_0^1a(r)^2\,
 \mathbb E\bigl[P_s(\sigma-\boldsymbol m_r)\cdot K_rP_s(\sigma-\boldsymbol m_r)\bigr]\,\mathrm d r .
\end{equation*}
Conditionally on $\mathcal G_r$, the matrix $K_r$ is fixed, and the residual $P_s(\sigma-\boldsymbol m_r)$ is centered with covariance $P_sC_rP_s$, whose only nonzero block is $C_{r,ss}$, by Lemma~\ref{l.response}. Hence $\mathbb E[P_s(\sigma-\boldsymbol m_r)\cdot K_rP_s(\sigma-\boldsymbol m_r)\mid\mathcal G_r]=\operatorname{tr}(K_rP_sC_rP_s)=\operatorname{tr}(K_{r,ss}C_{r,ss})$, which proves \eqref{e.posterior.variance}.

\label{l.scalar.ito}
Let $\nu\in\mathcal P([0,T])$, $s\in[0,T]$, $x\in\mathbb R$, and $X:=X^{s,x}$. For every $v\in[s,T]$,
\begin{equation}\label{e.magnetization.martingale}
 \partial_x\Phi(v,X_v)=\partial_x\Phi(s,x)+\sqrt2\int_s^v\partial_x^2\Phi(w,X_w)\,\mathrm d B_w,
\end{equation}
so that $M_v:=\partial_x\Phi(v,X_v)$ is a martingale with $M_T=\tanh X_T$. Moreover,
\begin{gather}
 \partial_x\Phi(s,x)=\mathbb E\bigl[\tanh X_T\bigr],\notag
 \\
 \partial_x^2\Phi(s,x)=1-\partial_x\Phi(s,x)^2
 -2\int_s^T\bigl(1-\zeta(w)\bigr)\mathbb E\bigl[\partial_x^2\Phi(w,X_w)^2\bigr]\,\mathrm d w,
 \label{e.gradient.representation}\\
 \Phi(s,x)=\mathbb E\bigl[\log\cosh X_T\bigr]
 -\int_s^T\zeta(w)\,\mathbb E\bigl[M_w^2\bigr]\,\mathrm d w.
 \label{e.scalar.optimal.value}
\end{gather}
In particular, \eqref{e.scalar.gradient.range} holds, $\Phi(v,\cdot)$ is strictly convex, $\partial_x\Phi$ is $1$-Lipschitz in $x$, and $M$ takes values in $(-1,1)$.

By Lemma~\ref{l.scalar.wellposed}, It\^o's formula applies to $\partial_x^j\Phi(w,X_w)$ for $j\leqslant2$, and the equations obtained by differentiating \eqref{e.scalar.pde} $j$ times in $x$ hold at every $w$ at which $\zeta$ is continuous, hence for almost every $w$. The drift of $\Phi(w,X_w)$ is $\partial_w\Phi+\partial_x^2\Phi+2\zeta(\partial_x\Phi)^2=\zeta(\partial_x\Phi)^2$, that of $\partial_x\Phi(w,X_w)$ is $\partial_w\partial_x\Phi+\partial_x^3\Phi+2\zeta\,\partial_x\Phi\,\partial_x^2\Phi=0$, and that of $\partial_x^2\Phi(w,X_w)$ is $\partial_w\partial_x^2\Phi+\partial_x^4\Phi+2\zeta\,\partial_x\Phi\,\partial_x^3\Phi=-2\zeta(\partial_x^2\Phi)^2$, all evaluated at $(w,X_w)$. The stochastic integrals have bounded integrands, hence zero mean. The second identity gives \eqref{e.magnetization.martingale}, and the first gives \eqref{e.scalar.optimal.value}, since $\Phi(T,\cdot)=\log\cosh$. Taking expectations in \eqref{e.magnetization.martingale} at $v=T$ gives $\partial_x\Phi(s,x)=\mathbb E[\tanh X_T]$, so $|\partial_x\Phi|<1$, and It\^o's isometry gives
\begin{equation*}
 \mathbb E\bigl[\tanh^2X_T\bigr]=\partial_x\Phi(s,x)^2+2\int_s^T\mathbb E\bigl[\partial_x^2\Phi(w,X_w)^2\bigr]\,\mathrm d w.
\end{equation*}
The third identity gives $\partial_x^2\Phi(s,x)=\mathbb E[1-\tanh^2X_T]+2\int_s^T\zeta(w)\mathbb E[\partial_x^2\Phi(w,X_w)^2]\,\mathrm d w$, which is positive, and substituting the previous display yields  \eqref{e.gradient.representation}, hence $0 < \partial_x^2\Phi\leqslant1-(\partial_x\Phi)^2$. The remaining assertions follow.

