\begin{equation*}
d(v,x)\geqslant\mathbb E\bigl[e^{\int_v^Tc(r,Y_r)\,\mathrm d r}d(T,Y_T)\bigr]=0,
\end{equation*} 
which is the upper bound in \eqref{e.barriers}; the lower bound is proved in the same way with $u_-$. The bijection statement follows from \eqref{e.scalar.gradient.range}, and the last identity is Fubini's theorem, since $1-\zeta_\nu(u)=\nu((u,T])$.

\label{l.dictionary}
Let $q$, $\nu$ and $u$ be as above, let $T:=q(1)$, and let $Z$ be a standard Gaussian random variable. We have
\begin{equation}\label{e.def.dictionary}
 \Phi_\nu(v,x)=
 \begin{cases}
 \mathbb E\,u\bigl(0,x+\sqrt{2(q(0)-v)}\,Z\bigr)&\text{if }0\leqslant v\leqslant q(0),\\
 u\bigl(q^{-1}(v),x\bigr)&\text{if }q(0)\leqslant v\leqslant q(1).
 \end{cases}
\end{equation}
In particular, for every $h\in\mathbb R$,
\begin{equation}\label{e.dictionary.value}
 \psi_\circ(\nu_q;h)=q(1)-\mathbb E\,u\bigl(0,h+\sqrt{2q(0)}\,Z\bigr).
\end{equation}

\label{p.scalar.martingale}
Let $\nu\in\mathcal P([0,T])$.
\begin{enumerate}
\item For every $y\in\mathbb R$,
\begin{equation}\label{e.scalar.sup.martingale}
 \Phi(0,y)=\sup_{\alpha\in\mathcal M_T}\Bigl\{y\,\alpha(0)+\mathbb E\bigl[\sqrt2\,\alpha(T)B(T)-I(\alpha(T))\bigr]
 +\int_0^T\zeta(v)\,\mathbb E[\alpha(v)^2]\,\mathrm d v\Bigr\},
\end{equation}
and the supremum is attained exactly at $\alpha=M^y$.
\item For every $m\in[-1,1]$,
\begin{equation}\label{e.scalar.martingale}
 g_m(\nu)=\inf_{\alpha\in\mathcal M_T^m}
             \left\{c_T(\alpha)+\int\chi_\alpha\,\mathrm d\nu\right\}.
\end{equation}
For $|m|<1$, the infimum is attained at $M^{y(\nu,m)}$. For $m=\pm1$, it is attained at the constant martingale $\alpha\equiv m$, and
\begin{equation}\label{e.g.endpoints}
 g_{\pm1}(\nu)=\log2+\int v\,\nu(\mathrm d v).
\end{equation}
\end{enumerate}

